    return { ...construction('Keep the missing evaluations visible', 'Botie wants to compare prompt revisions, but scoring finishes out of order and some runs have no judgement.', 'Select the requested rubric, attach its scores by trace ID, and keep the requested prompt version. Return [mean of available scores, scored fraction]. A zero counts as scored; missing remains null. Each case includes at least one selected run.', { runs: 'Recorded runs and prompt revisions', scores: 'Trace scores and rubric revisions', rubric: 'Requested rubric revision', version: 'Requested prompt revision' }, [sample('Scores arrive out of order', { runs: [run('A', 3), run('B', 3), run('C', 2)], scores: [score('B', 1), score('C', 1), score('A', 0)], rubric: 'grounded-v2', version: 3 }, [0.5, 1]), sample('A run never received its judgement', { runs: [run('A', 3), run('B', 3), run('C', 3)], scores: [score('B', 1), score('A', 0)], rubric: 'grounded-v2', version: 3 }, [0.5, 2 / 3]), sample('The older rubric disagrees', { runs: [run('A', 4), run('B', 4)], scores: [score('A', 1, 'grounded-v1'), score('B', 1, 'grounded-v1'), score('A', 0, 'grounded-v2'), score('B', 0, 'grounded-v2')], rubric: 'grounded-v2', version: 4 }, [0, 1])], op('pack', op('agentObsMeanScore', selected), op('divide', op('count', op('agentObsScored', selected)), op('count', selected))), 'The score identity and evaluation coverage survive changes in arrival order, prompt revision and evaluator revision.', 'These simplified records allow one score per trace for the selected rubric. Real systems also distinguish observation IDs, evaluator sources and repeated runs.'), hints: ['Filter score rows by rubric before joining, so two evaluator revisions are not treated as duplicates.', 'Filter the joined runs by promptVersion. Feed the same selected runs to the mean and coverage branches.', 'Divide the count of scored runs by the count of all selected runs, then collect the mean and fraction.'] };
